-- SKU Master: bulk INSERT .. ON DUPLICATE KEY UPDATE for every sku_code in the
-- business's full SKU master spreadsheet ("packig material code wise details"
-- xlsx, MASTER DATA sheet, 825 distinct sku_code rows with a non-blank
-- scanning/conveyor value -- same source V279 read).
--
-- V279 was a plain UPDATE, so it only touched the subset of these sku_codes
-- already present in a given database's catalog. This migration is the
-- superset fix, same pattern as V273's sku_master_upsert_full_catalog:
-- INSERT .. ON DUPLICATE KEY UPDATE against the (tenant_id, sku_code) UNIQUE
-- KEY (uq_sku_code) -- creates a minimal new row (defaults fill every other
-- column, e.g. pack_pieces_per_case=12, gst_rate_pct=5.00, status=ACTIVE) for a
-- sku_code missing from the catalog, carrying product_family/sku_name straight
-- from the sheet (blank SKU Section -> '' product_family, matching this table's
-- existing convention for uncategorized legacy rows).
--
-- Deliberately does NOT overwrite product_family/sku_name for a sku_code that
-- already has a row (e.g. SPR0091/SPR0060/etc, onboarded earlier by V273 with a
-- '99 GIFT' placeholder category) -- only scanning_status/conveyor_mode refresh
-- on conflict, so this never clobbers a category a human already curated.
--
-- Idempotent -- safe to (re)run on any database.

INSERT INTO m5_sku_master (tenant_id, sku_code, product_family, sku_name, scanning_status, conveyor_mode)
SELECT 1, map.sku_code, map.product_family, map.sku_name, map.scanning_status, map.conveyor_mode
FROM (
    SELECT 'SKU1005' AS sku_code, '05 GINGELLY OIL' AS product_family, 'GINGELLY OIL RS.15 PACK BOX (08.01.25)' AS sku_name, 'BARCODE' AS scanning_status, 'CONVEYOR' AS conveyor_mode
    UNION ALL SELECT 'SKU1007', '05 GINGELLY OIL', 'GINGELLY OIL RS.40 PACK BOX (08.01.25)', 'BARCODE', 'CONVEYOR'
    UNION ALL SELECT 'SKU1012', '01 GROUNDNUT OIL', 'GROUNDNUT RAW OIL 1 LTR BOX GULAS OFFER', 'BARCODE', 'CONVEYOR'
